      const svg = new TextDecoder("utf-8", { fatal: false }).decode(bytes);
      if (/<svg[\s>]/i.test(svg)) {
        const normalized = normalizeSvgMarkup(svg);
        const normalizedBytes = new TextEncoder().encode(normalized);
