    if (!baseUrl && !/^https?:\/\//i.test(trimmed)) return undefined;
    const target = baseUrl ? new URL(trimmed, baseUrl) : new URL(trimmed);
    return target.protocol === "http:" || target.protocol === "https:" ? target.href : undefined;
  } catch {
    return undefined;
  }
}

