 1	import { afterEach, describe, expect, it, vi } from "vitest";
 2	import { buildNetworkShim, isSafeBaseUrl, prepareSandboxDocument } from "./prepareDocument";
 3	import type { ViewportSpec } from "../shared/contracts";
 4	
 5	const viewport: ViewportSpec = { id: "desktop", name: "Desktop", width: 1440, height: 900 };
 6	
 7	afterEach(() => {
 8	  vi.unstubAllGlobals();
 9	  vi.unstubAllEnvs();
10	  delete (globalThis as { location?: Location }).location;
11	});
12	
13	describe("sandbox document preparation", () => {
14	  it("accepts only web base URLs", () => {
15	    expect(isSafeBaseUrl("https://example.com/assets/")).toBe(true);
16	    expect(isSafeBaseUrl("javascript:alert(1)")).toBe(false);
17	    expect(isSafeBaseUrl("file:///tmp/page")).toBe(false);
18	  });
19	
20	  it("removes supplied scripts when scripts are disabled", () => {
21	    const result = prepareSandboxDocument({ html: "<script>window.bad = true</script><main>Hello</main>", baseUrl: "https://example.com/", scriptPolicy: "off", token: "test", viewport, settleDelayMs: 0 });
22	    expect(result).not.toContain("window.bad");
23	    expect(result).toContain("data-html-to-penpot-scripts-disabled=\"1\"");
24	    expect(result).toContain("Content-Security-Policy");
25	    expect(result).toContain("<base href=\"https://example.com/\">");
26	  });
27	
28	  it("keeps trusted scripts but gives them a nonce", () => {
29	    const result = prepareSandboxDocument({ html: "<script src=\"app.js\"></script>", scriptPolicy: "trusted", token: "test", viewport, settleDelayMs: 0 });
30	    expect(result).toContain("src=\"app.js\" nonce=");
31	    expect(result).toContain("connect-src http: https:");
32	  });
33	
34	  it("prepends the network shim ahead of page scripts in trusted mode with a proxy", () => {
35	    (globalThis as { location?: Location }).location = { origin: "http://localhost:4173", hostname: "localhost" } as Location;
36	    const html = "<head><script>var first = true;</script></head><body></body>";
37	    const result = prepareSandboxDocument({ html, baseUrl: "https://example.com/page", scriptPolicy: "trusted", token: "test", viewport, settleDelayMs: 0 });
38	    const shimIndex = result.indexOf("mode=asset");
39	    const scriptIndex = result.indexOf("var first");
40	    expect(shimIndex).toBeGreaterThan(-1);
41	    expect(shimIndex).toBeLessThan(scriptIndex);
42	    expect(result).toContain("http://localhost:4173/__html_to_penpot/fetch");
43	    expect(result).toContain('"https://example.com"');
44	  });
45	
46	  it("injects the build-time service proxy into the trusted shim", () => {
47	    (globalThis as { location?: Location }).location = { origin: "http://localhost:4173", hostname: "localhost" } as Location;
48	    vi.stubEnv("VITE_FETCH_PROXY_ORIGIN", "https://svc.example.com/");
49	    const result = prepareSandboxDocument({ html: "<body></body>", baseUrl: "https://example.com/", scriptPolicy: "trusted", token: "test", viewport, settleDelayMs: 0 });
50	    expect(result).toContain('"https://svc.example.com/api/fetch-html"');
51	    expect(result).not.toContain("__html_to_penpot/fetch");
52	  });
53	
54	  it("omits the network shim when scripts are off", () => {
55	    (globalThis as { location?: Location }).location = { origin: "http://localhost:4173", hostname: "localhost" } as Location;
56	    const result = prepareSandboxDocument({ html: "<script>x()</script><body></body>", baseUrl: "https://example.com/", scriptPolicy: "off", token: "test", viewport, settleDelayMs: 0 });
57	    expect(result).not.toContain("mode=asset");
58	  });
59	
60	  it("omits the network shim when no proxy is configured", () => {
61	    (globalThis as { location?: Location }).location = { origin: "https://plugin.example.com", hostname: "plugin.example.com" } as Location;
62	    const result = prepareSandboxDocument({ html: "<body></body>", baseUrl: "https://example.com/", scriptPolicy: "trusted", token: "test", viewport, settleDelayMs: 0 });
63	    expect(result).not.toContain("mode=asset");
64	  });
65	
66	  it("rewrites only same-origin GET requests to the page origin", () => {
67	    const shim = buildNetworkShim("https://example.com", "https://svc.example.com/api/fetch-html");
68	    expect(shim).toContain("baseOrigin");
69	    expect(shim).toContain('"GET"');
70	    // The shim body must not rewrite by default; assertions on behavior live
71	    // in browser-level integration tests.
72	    expect(shim).toContain("mode=asset");
73	  });
74	});

