  8	/** Run the async capture script as the sandbox host does: only its matching
  9	 * token may complete this invocation, and listeners/timers always clean up. */
 10	function captureScript(token: string, viewport = TEST_VIEWPORT): Promise<SceneDocument> {
 11	  return new Promise((resolve, reject) => {
 12	    const cleanup = () => {
 13	      window.removeEventListener("message", receive);
 14	      window.clearTimeout(timeout);
 15	    };
 16	    const receive = (event: MessageEvent) => {
 17	      if (event.data?.token !== token) return;
 18	      if (event.data.type === "CAPTURE_RESULT") {
 19	        cleanup();
 20	        resolve(event.data.scene as SceneDocument);
 21	      } else if (event.data.type === "CAPTURE_ERROR") {
 22	        cleanup();
 23	        reject(new Error(event.data.message || "Capture failed."));
 24	      }
 25	    };
 26	    const timeout = window.setTimeout(() => {
 27	      cleanup();
 28	      reject(new Error(`Capture ${token} did not complete within the test timeout.`));
