 16	const FONT_FACE_PATTERN = /@font-face\s*\{[^{}]*\}/g;
 17	const URL_PATTERN = /url\(\s*(['"]?)([^'")]+)\1\s*\)/g;
 18	/** Legacy formats browsers only try after the modern ones fail; dropping them keeps overrides small. */
 19	const LEGACY_FONT_URL = /\.(?:eot|svg)(?:[?#]|$)/;
