 21	/** Every webfont URL referenced by @font-face rules in a stylesheet. */
 22	function fontUrlsOf(css: string): string[] {
 23	  const urls: string[] = [];
 24	  for (const block of css.match(FONT_FACE_PATTERN) || []) {
 25	    for (const segment of block.match(SOURCE_SEGMENT_PATTERN) || []) {
 26	      for (const match of segment.matchAll(URL_PATTERN)) {
 27	        const url = match[2].trim();
 28	        if (!url || url.startsWith("data:") || url.startsWith("blob:") || /^local\(/i.test(url) || LEGACY_FONT_URL.test(url)) continue;
 29	        urls.push(url);
 30	      }
 31	    }
 32	  }
 33	  return urls;
