 36	/** Segments of a src list that reference a font file, e.g. `url(x) format('woff2')`. */
 37	const SOURCE_SEGMENT_PATTERN = /[^,()]*url\([^)]*\)\s*(?:format\([^)]*\)\s*)?[^,;]*/g;
 38	const SRC_PROPERTY_PATTERN = /src\s*:\s*[^;}]*(;|$)/g;
 39	
 40	/**
 41	 * Re-point every fetchable url() in an @font-face rule at its inlined data
 42	 * equivalent. Rules whose fonts could not be fetched are dropped whole: a
 43	 * rule keeping the remote reference would still be CORS-blocked in the
 44	 * sandbox and only re-trigger the failed load. Legacy EOT/SVG sources are
 45	 * dropped rather than fetched — modern browsers never reach them, and their
 46	 * bytes (SVG fonts in particular) can be large.
 47	 */
 48	function rebasedFontFaces(css: string, dataUrls: Map<string, string>): string[] {
 49	  const rules: string[] = [];
 50	  for (const block of css.match(FONT_FACE_PATTERN) || []) {
 51	    const segments = block.match(SOURCE_SEGMENT_PATTERN) || [];
 52	    const kept = segments.filter((segment) => ![...segment.matchAll(URL_PATTERN)].some((match) => LEGACY_FONT_URL.test(match[2].trim())));
 53	    // Rules with only legacy sources have no modern fallback to rewrite.
 54	    if (!kept.length) continue;
 55	    const urls = kept.flatMap((segment) => [...segment.matchAll(URL_PATTERN)]).map((match) => match[2].trim()).filter((url) => !url.startsWith("data:") && !url.startsWith("blob:"));
 56	    if (!urls.length || !urls.every((url) => dataUrls.has(url))) continue;
 57	    const rewritten = kept.map((segment) => segment.replace(URL_PATTERN, (match, _quote: string, url: string) => dataUrls.has(url) ? `url("${dataUrls.get(url)}")` : match)).join(",");
 58	    // Rebuild with every original src declaration replaced by the rewritten
 59	    // one so descriptors keep their order-independent meaning.
 60	    const opening = block.indexOf("{");
 61	    const body = block.slice(opening + 1, block.lastIndexOf("}"));
 62	    rules.push(`${block.slice(0, opening + 1)}${body.replace(SRC_PROPERTY_PATTERN, "")}src:${rewritten};}`);
 63	  }
 64	  return rules;
 65	}
