 76	function base64Of(bytes: Uint8Array): string {
 77	  let binary = "";
 78	  const chunk = 0x8000;
 79	  for (let index = 0; index < bytes.length; index += chunk) {
 80	    binary += String.fromCharCode(...bytes.subarray(index, index + chunk));
