 59	    // one so descriptors keep their order-independent meaning.
 60	    const opening = block.indexOf("{");
 61	    const body = block.slice(opening + 1, block.lastIndexOf("}"));
 62	    rules.push(`${block.slice(0, opening + 1)}${body.replace(SRC_PROPERTY_PATTERN, "")}src:${rewritten};}`);
 63	  }
 64	  return rules;
 65	}
