 67	function extensionOf(url: string): string {
 68	  try {
 69	    const path = new URL(url).pathname;
 70	    return path.slice(path.lastIndexOf(".")).toLowerCase();
 71	  } catch {
 72	    return "";
 73	  }
 74	}
