 85	async function fontDataUrl(url: string): Promise<string | undefined> {
 86	  const response = await fetchDocument(url, "font");
 87	  const buffer = new Uint8Array(await response.arrayBuffer());
 88	  if (!buffer.byteLength || buffer.byteLength > MAX_FONT_BYTES) return undefined;
 89	  const declared = response.headers.get("content-type")?.split(";")[0].trim().toLowerCase();
 90	  const mimeType = declared && /^(font\/|application\/(font|x-font|vnd\.ms-fontobject|octet-stream))/.test(declared) && declared !== "application/octet-stream"
 91	    ? declared
 92	    : FONT_MIME_BY_EXTENSION[extensionOf(url)] || "application/octet-stream";
 93	  return `data:${mimeType};base64,${base64Of(buffer)}`;
 94	}
