 96	/**
 97	 * Inline the page's webfonts as data: URLs appended in a trailing override
 98	 * stylesheet. The capture sandbox is an opaque origin, and browsers always
 99	 * fetch fonts in CORS mode, so @font-face fonts from hosts without
100	 * `Access-Control-Allow-Origin` silently fall back to system fonts and every
101	 * measured text box drifts from the real site. Fetching here (directly when
102	 * the host allows it, otherwise through the constrained import service) and
103	 * appending `data:`-sourced copies of the same @font-face rules restores the
104	 * site's real font metrics inside the sandbox. Existing markup and styles
105	 * are never modified; the original declarations keep working as a fallback.
106	 */
107	export async function inlineWebFonts(html: string, baseUrl?: string): Promise<string> {
108	  // Font rules may live in linked stylesheets rather than the markup itself,
109	  // so the cheap text check alone cannot rule the pass out.
110	  if (!baseUrl || typeof DOMParser === "undefined" || (!html.includes("@font-face") && !html.includes("<link"))) return html;
111	
112	  const document = new DOMParser().parseFromString(html, "text/html");
113	  const stylesheets: string[] = [];
114	  for (const style of document.querySelectorAll("style")) stylesheets.push(style.textContent || "");
115	
116	  await Promise.all([...document.querySelectorAll("link[rel~='stylesheet'][href]")].map(async (link) => {
117	    const href = link.getAttribute("href");
118	    if (!href) return;
119	    try {
120	      const target = new URL(href, baseUrl);
121	      if (target.protocol !== "https:" && target.protocol !== "http:") return;
122	      const response = await fetchDocument(target.href, "css");
123	      const css = await response.text();
124	      if (utf8ByteLength(css) <= MAX_STYLESHEET_BYTES) stylesheets.push(css);
125	    } catch {
126	      // Linked fonts stay remote when the stylesheet cannot be read; the
127	      // sandbox behaves exactly as it would have without this pass.
128	    }
129	  }));
130	
131	  const urls = [...new Set(stylesheets.flatMap(fontUrlsOf))].slice(0, MAX_FONT_URLS);
132	  const dataUrls = new Map<string, string>();
133	  await Promise.all(urls.map(async (url) => {
134	    try {
135	      const absolute = new URL(url, baseUrl);
136	      if (absolute.protocol !== "https:" && absolute.protocol !== "http:") return;
137	      const dataUrl = await fontDataUrl(absolute.href);
138	      if (dataUrl) dataUrls.set(url, dataUrl);
139	    } catch {
140	      // A font the service cannot reach stays remote; capture falls back to
141	      // system fonts for that family only.
142	    }
143	  }));
144	  if (!dataUrls.size) return html;
145	
146	  const rules = stylesheets.flatMap((css) => rebasedFontFaces(css, dataUrls));
147	  if (!rules.length) return html;
148	
149	  const override = document.createElement("style");
150	  override.setAttribute("data-html-to-penpot-fonts", "");
151	  override.textContent = rules.join("\n");
152	  (document.head || document.documentElement).append(override);
153	  return "<!doctype html>\n" + document.documentElement.outerHTML;
154	}
