134	function normalizeSvgMarkup(svg: string): string {
135	  if (typeof DOMParser === "undefined") return svg;
136	  let document: Document;
137	  try {
138	    document = new DOMParser().parseFromString(svg, "image/svg+xml");
139	  } catch {
140	    return svg;
141	  }
142	  const root = document.documentElement;
143	  if (!root || root.tagName.toLowerCase() !== "svg") return svg;
