  1	import { prepareSandboxDocument } from "./prepareDocument";
  2	import type { CaptureRequest, SceneDocument, ViewportSpec } from "../shared/contracts";
  3	
  4	const CAPTURE_TIMEOUT_MS = 15_000;
  5	
  6	export async function captureViewport(request: Omit<CaptureRequest, "viewports">, viewport: ViewportSpec): Promise<SceneDocument> {
  7	  const token = crypto.randomUUID();
  8	  const iframe = document.createElement("iframe");
  9	  iframe.setAttribute("sandbox", "allow-scripts");
 10	  iframe.setAttribute("referrerpolicy", "no-referrer");
 11	  iframe.setAttribute("aria-hidden", "true");
 12	  // `visibility:hidden` can suspend requestAnimationFrame and font loading in a
 13	  // Chromium iframe. Keep the renderer active while making it imperceptible.
 14	  iframe.style.cssText = `position:fixed;left:-20000px;top:0;width:${viewport.width}px;height:${viewport.height}px;border:0;opacity:0;pointer-events:none;`;
 15	  document.body.append(iframe);
 16	
 17	  return new Promise<SceneDocument>((resolve, reject) => {
 18	    const finish = (callback: () => void) => {
 19	      window.removeEventListener("message", receive);
 20	      window.clearTimeout(timeout);
 21	      iframe.remove();
 22	      callback();
 23	    };
 24	    const receive = (event: MessageEvent) => {
 25	      if (event.source !== iframe.contentWindow || !event.data || event.data.token !== token) return;
 26	      if (event.data.type === "CAPTURE_RESULT") finish(() => resolve(event.data.scene as SceneDocument));
 27	      if (event.data.type === "CAPTURE_ERROR") finish(() => reject(new Error(event.data.message || "Capture failed.")));
 28	    };
 29	    const timeout = window.setTimeout(() => finish(() => reject(new Error(`${viewport.name} did not settle within 15 seconds.`))), CAPTURE_TIMEOUT_MS);
 30	    window.addEventListener("message", receive);
 31	    iframe.srcdoc = prepareSandboxDocument({ ...request, viewport, token });
 32	  });
 33	}
 34	
 35	export async function capturePage(request: CaptureRequest, onProgress?: (completed: number, total: number) => void): Promise<SceneDocument[]> {
 36	  const { viewports, ...shared } = request;
