294	function applyPenpotFontFamily(text: Text, value: string | undefined): void {
295	  for (const family of penpotFontCandidates(value)) {
296	    try {
297	      text.fontFamily = family;
298	      return;
299	    } catch {
300	      // Browser fonts are not necessarily installed in Penpot. Try the
301	      // normalized family and finally the guaranteed Inter fallback.
302	    }
303	  }
