399	function needsContainerBackdrop(node: SceneNode): boolean {
400	  const paint = node.paint;
401	  return Boolean(
402	    cssColor(paint.backgroundColor) ||
403	    (paint.backgroundImage && paint.backgroundImage !== "none") ||
404	    (paint.borderWidth && paint.borderWidth > 0 && paint.borderStyle !== "none") ||
405	    (paint.boxShadow && paint.boxShadow !== "none") ||
406	    paint.radius?.some((radius) => radius > 0)
407	  );
408	}
