442	async function createContainerBackdrop(node: SceneNode, assets: Map<string, AssetRef>, media: MediaCache): Promise<Shape> {
443	  const backdrop = penpot.createRectangle();
444	  // Opacity belongs to the complete container compositing group. Keeping
445	  // the backdrop fully opaque lets the group apply it once to both the
446	  // background and editable descendants.
447	  applyPaint(backdrop, { ...node.paint, opacity: 1 });
448	  const asset = node.assetId ? assets.get(node.assetId) : undefined;
449	  if (asset && !(await applyAssetFill(backdrop, asset, media))) {
450	    markAssetFallback(backdrop, "Background image could not be loaded; a placeholder is shown.");
451	  }
452	  return backdrop;
453	}
454	
455	function applyContainerOpacity(shape: Shape, node: SceneNode): void {
456	  const opacity = node.paint.opacity;
457	  if (opacity === undefined || opacity === 1) return;
458	  shape.opacity = (shape.opacity ?? 1) * opacity;
459	}
460	
461	function metadata(shape: Shape, node: SceneNode, viewportId: string): void {
462	  let assetFallback = "";
463	  const getPluginData = (shape as Shape & { getPluginData?: (key: string) => string }).getPluginData;
464	  if (typeof getPluginData === "function") {
465	    try { assetFallback = getPluginData.call(shape, "asset-fallback"); } catch { /* Older hosts may not expose plugin data reads. */ }
466	  }
467	  shape.name = assetFallback
468	    ? `${assetFallback.startsWith("SVG") ? "SVG fallback" : "Image unavailable"}: ${node.name}`.slice(0, 200)
469	    : node.name.slice(0, 200);
470	  shape.setPluginData("importer", IMPORT_NAMESPACE);
471	  shape.setPluginData("viewport", viewportId);
472	  shape.setPluginData("source", node.source);
473	  if (node.fallbackReason) shape.setPluginData("fallback", node.fallbackReason);
474	}
475	
476	async function createShape(node: SceneNode, assets: Map<string, AssetRef>, media: MediaCache): Promise<Shape> {
477	  if (node.kind === "text") return createText(node);
478	  const asset = node.assetId ? assets.get(node.assetId) : undefined;
479	  const svg = svgTextOf(asset);
480	  let svgConversionFailed = node.kind === "svg" || Boolean(svg);
481	  if (svg) {
482	    try {
483	      const group = await penpot.createShapeFromSvgWithImages(svg);
484	      if (group) return group;
485	    } catch {
486	      // Try the synchronous converter for SVGs without image dependencies.
487	    }
488	    try {
489	      const group = penpot.createShapeFromSvg(svg);
490	      if (group) return group;
491	    } catch {
492	      // Keep an image-backed rectangle if the SVG uses features Penpot cannot
493	      // translate into editable vectors.
494	    }
495	  }
496	  const shape = penpot.createRectangle();
497	  if (node.kind === "fallback") {
498	    (shape as Shape & { fills: Fill[] }).fills = [{ fillColor: "#f4f4f5" }];
499	    shape.name = `Unsupported: ${node.name}`;
500	  } else {
501	    applyPaint(shape, node.paint);
502	  }
503	  if ((node.kind === "image" || node.kind === "svg" || node.paint.backgroundImage?.includes("url(")) && node.assetId) {
504	    const applied = await applyAssetFill(shape, asset, media);
505	    if (svgConversionFailed && applied) markAssetFallback(shape, "SVG vector conversion failed; the uploaded image fallback is shown.");
506	    else if (!applied) markAssetFallback(shape, node.kind === "svg" ? "SVG could not be converted or loaded; an image placeholder is shown." : "Image could not be loaded; an image placeholder is shown.");
507	  }
508	  return shape;
509	}
