511	export async function importScenes(scenes: SceneDocument[], options: ImportOptions): Promise<Board[]> {
512	  const boards: Board[] = [];
513	  const total = scenes.reduce((sum, scene) => sum + scene.nodes.length, 0);
514	  let completed = 0;
515	  const origin = { x: penpot.viewport.center.x, y: penpot.viewport.center.y };
516	  let x = origin.x;
517	  // Keep one uploaded media object per source URL across responsive boards.
518	  // Re-uploading the same page asset for each viewport creates noisy failed
519	  // requests in Penpot and needlessly increases the file update payload.
520	  const media: MediaCache = new Map();
521	
522	  try {
523	    for (const scene of scenes) {
524	      if (options.isCancelled()) throw new ImportCancelledError();
525	      const undo = penpot.history.undoBlockBegin();
526	      try {
527	        const board = penpot.createBoard();
528	        boards.push(board);
529	        board.name = `Page — ${scene.viewport.name} ${scene.viewport.width}`;
530	        board.x = x;
531	        board.y = origin.y;
532	        board.resize(scene.viewport.width, scene.documentSize.height);
533	        board.clipContent = true;
534	        board.setPluginData("importer", IMPORT_NAMESPACE);
535	        board.setPluginData("viewport", scene.viewport.id);
536	        x += scene.viewport.width + 120;
537	
538	        const nodes = new Map(scene.nodes.map((node) => [node.id, node]));
539	        const childrenByParent = new Map<string, SceneNode[]>();
540	        for (const node of scene.nodes) {
541	          if (!node.parentId || !nodes.has(node.parentId)) continue;
542	          const siblings = childrenByParent.get(node.parentId) || [];
543	          siblings.push(node);
544	          childrenByParent.set(node.parentId, siblings);
545	        }
546	        const assets = new Map(scene.assets.map((asset) => [asset.id, asset]));
547	        const shapes = new Map<string, Shape>();
548	        const textLines: { text: Text; node: SceneNode; maximum: number }[] = [];
549	        const roots = scene.nodes.filter((node) => !node.parentId || !nodes.has(node.parentId));
550	
551	        const append = (parentShape: Board | Shape, shape: Shape) => {
552	          if (parentShape.type === "board") (parentShape as Board).appendChild(shape);
553	          else (parentShape as Shape & { appendChild?: (child: Shape) => void }).appendChild?.(shape);
554	        };
555	
556	        const reportProgress = () => {
557	          completed += 1;
558	          if (completed % 25 === 0 || completed === total) {
559	            options.onProgress(completed, total, `Creating ${scene.viewport.name}`);
560	          }
561	        };
562	
563	        const render = async (node: SceneNode, parentShape: Board | Shape): Promise<Shape | undefined> => {
564	          if (options.isCancelled()) throw new ImportCancelledError();
565	          if (node.kind === "container" && clipsContent(node.paint)) {
566	            // A Penpot board is the clipping-capable container. Unlike a
567	            // group, its bounds stay at the captured element's box instead of
568	            // growing to enclose its descendants, so an oversized child is
569	            // hidden rather than resizing the container. The board also paints
570	            // the element's own decoration, which keeps the clip and the
571	            // rounded corners on one surface.
572	            const clip = penpot.createBoard();
573	            clip.clipContent = true;
574	            applyPaint(clip, node.paint);
575	            const clipAsset = node.assetId ? assets.get(node.assetId) : undefined;
576	            if (clipAsset && !(await applyAssetFill(clip, clipAsset, media))) {
577	              markAssetFallback(clip, "Background image could not be loaded; a placeholder is shown.");
578	            }
579	            metadata(clip, node, scene.viewport.id);
580	            append(parentShape, clip);
581	            // Establish parentage and the container's own bounds before its
582	            // children: applyGeometry writes page-space coordinates, and the
583	            // children are positioned against the same page origin.
584	            applyGeometry(clip, node, { x: board.x, y: board.y });
585	            shapes.set(node.id, clip);
586	            for (const child of childrenByParent.get(node.id) || []) await render(child, clip);
587	            reportProgress();
588	            return clip;
589	          }
590	          if (node.kind === "container") {
591	            const children: Shape[] = [];
592	            for (const child of childrenByParent.get(node.id) || []) {
593	              const childShape = await render(child, parentShape);
594	              if (childShape) children.push(childShape);
595	            }
596	
597	            const backdrop = needsContainerBackdrop(node) ? await createContainerBackdrop(node, assets, media) : undefined;
598	            if (backdrop) {
599	              metadata(backdrop, node, scene.viewport.id);
600	              append(parentShape, backdrop);
601	              applyGeometry(backdrop, node, { x: board.x, y: board.y });
602	              children.unshift(backdrop);
603	            }
604	
605	            if (!children.length) {
606	              reportProgress();
607	              return undefined;
608	            }
609	            const shape = children.length === 1 ? children[0] : penpot.group(children);
610	            if (!shape) {
611	              reportProgress();
612	              return children[0];
613	            }
614	            applyContainerOpacity(shape, node);
615	            metadata(shape, node, scene.viewport.id);
616	            shapes.set(node.id, shape);
617	            reportProgress();
618	            return shape;
619	          }
