690	      // the next board. This keeps network requests and undo history bounded.
691	      await new Promise<void>((resolve) => setTimeout(resolve, 250));
692	    }
693	    return boards;
694	  } catch (error) {
695	    for (const board of boards) board.remove();
696	    throw error;
697	  }
698	}

