  2	import type { CaptureRequest, SceneDocument, ViewportSpec } from "../shared/contracts";
  3	
  4	const CAPTURE_TIMEOUT_MS = 15_000;
  5	
  6	export async function captureViewport(request: Omit<CaptureRequest, "viewports">, viewport: ViewportSpec): Promise<SceneDocument> {
  7	  const token = crypto.randomUUID();
  8	  const iframe = document.createElement("iframe");
  9	  iframe.setAttribute("sandbox", "allow-scripts");
