148	
149	  const override = document.createElement("style");
150	  override.setAttribute("data-html-to-penpot-fonts", "");
151	  override.textContent = rules.join("\n");
152	  (document.head || document.documentElement).append(override);
153	  return "<!doctype html>\n" + document.documentElement.outerHTML;
