476	async function createShape(node: SceneNode, assets: Map<string, AssetRef>, media: MediaCache): Promise<Shape> {
477	  if (node.kind === "text") return createText(node);
478	  const asset = node.assetId ? assets.get(node.assetId) : undefined;
479	  const svg = svgTextOf(asset);
480	  let svgConversionFailed = node.kind === "svg" || Boolean(svg);
481	  if (svg) {
482	    try {
483	      const group = await penpot.createShapeFromSvgWithImages(svg);
484	      if (group) return group;
485	    } catch {
486	      // Try the synchronous converter for SVGs without image dependencies.
487	    }
488	    try {
489	      const group = penpot.createShapeFromSvg(svg);
490	      if (group) return group;
491	    } catch {
492	      // Keep an image-backed rectangle if the SVG uses features Penpot cannot
493	      // translate into editable vectors.
494	    }
495	  }
496	  const shape = penpot.createRectangle();
497	  if (node.kind === "fallback") {
498	    (shape as Shape & { fills: Fill[] }).fills = [{ fillColor: "#f4f4f5" }];
499	    shape.name = `Unsupported: ${node.name}`;
500	  } else {
501	    applyPaint(shape, node.paint);
502	  }
503	  if ((node.kind === "image" || node.kind === "svg" || node.paint.backgroundImage?.includes("url(")) && node.assetId) {
504	    const applied = await applyAssetFill(shape, asset, media);
505	    if (svgConversionFailed && applied) markAssetFallback(shape, "SVG vector conversion failed; the uploaded image fallback is shown.");
506	    else if (!applied) markAssetFallback(shape, node.kind === "svg" ? "SVG could not be converted or loaded; an image placeholder is shown." : "Image could not be loaded; an image placeholder is shown.");
507	  }
508	  return shape;
509	}
