  3	import { ImportCancelledError, importScenes } from "./penpot";
  4	
  5	type FakeShape = Record<string, unknown> & { type: string; children?: FakeShape[]; removed?: boolean };
  6	
  7	function fakeShape(type: string): FakeShape {
  8	  return {
  9	    type,
 10	    name: "",
 11	    x: 0,
 12	    y: 0,
 13	    opacity: 1,
 14	    strokes: [],
 15	    children: [],
 16	    pluginData: {},
 17	    resize: vi.fn(),
 18	    setPluginData: vi.fn(function (this: FakeShape, key: string, value: string) { (this.pluginData as Record<string, string>)[key] = value; }),
 19	    getPluginData: vi.fn(function (this: FakeShape, key: string) { return String((this.pluginData as Record<string, string>)[key] || ""); }),
 20	    appendChild: vi.fn(function (this: FakeShape, child: FakeShape) { this.children?.push(child); }),
 21	    remove: vi.fn(function (this: FakeShape) { this.removed = true; })
 22	  };
 23	}
 24	
 25	function scene(name = "Desktop"): SceneDocument {
 26	  return {
 27	    protocolVersion: PROTOCOL_VERSION,
 28	    viewport: { id: name.toLowerCase(), name, width: 400, height: 300 },
 29	    documentSize: { width: 400, height: 300 },
 30	    assets: [],
 31	    diagnostics: [],
 32	    nodes: [{ id: "root", children: ["text"], kind: "container", name: "body", source: "body", rect: { x: 0, y: 0, width: 400, height: 300 }, zIndex: 1, paint: { backgroundColor: "rgb(255, 255, 255)" }, layout: { kind: "flex", direction: "column" } }, { id: "text", parentId: "root", children: [], kind: "text", name: "Hello", source: "body ::text", rect: { x: 20, y: 20, width: 80, height: 24 }, zIndex: 2, paint: { color: "rgb(0, 0, 0)" }, layout: { kind: "none" }, text: "Hello", textStyle: { fontFamily: "Inter", fontSize: 16, fontWeight: 400, fontStyle: "normal", lineHeight: 1.5, letterSpacing: 0, textAlign: "left", textDecoration: "none", textTransform: "none" } }]
 33	  };
 34	}
