 36	describe("Penpot importer", () => {
 37	  let boards: FakeShape[];
 38	  let undoFinish: ReturnType<typeof vi.fn>;
 39	
 40	  beforeEach(() => {
 41	    boards = [];
 42	    undoFinish = vi.fn();
 43	    vi.stubGlobal("penpot", {
 44	      viewport: { center: { x: 100, y: 200 } },
 45	      history: { undoBlockBegin: vi.fn(() => Symbol("undo")), undoBlockFinish: undoFinish },
 46	      createBoard: vi.fn(() => {
 47	        const board = fakeShape("board");
 48	        Object.assign(board, { clipContent: false, showInViewMode: true, fills: [], flex: undefined, addFlexLayout: vi.fn(function (this: FakeShape) { const flex = { appendChild: vi.fn((child: FakeShape) => board.children?.push(child)), dir: "row", wrap: "nowrap", rowGap: 0, columnGap: 0, topPadding: 0, rightPadding: 0, bottomPadding: 0, leftPadding: 0 }; board.flex = flex; return flex; }) });
 49	        boards.push(board);
 50	        return board;
 51	      }),
 52	      createRectangle: vi.fn(() => Object.assign(fakeShape("rectangle"), { fills: [] })),
 53	      createText: vi.fn((characters: string) => {
 54	        const shape = Object.assign(fakeShape("text"), { characters, fills: [], growType: "fixed" });
 55	        let fontFamily = "";
 56	        Object.defineProperty(shape, "fontFamily", {
 57	          configurable: true,
 58	          get: () => fontFamily,
 59	          set: (value: string) => {
 60	            if (value === "Poppins-Regular") throw new Error("font family is not installed");
 61	            fontFamily = value;
 62	          }
 63	        });
 64	        return shape;
 65	      }),
 66	      group: vi.fn((shapes: FakeShape[]) => Object.assign(fakeShape("group"), { children: shapes })),
 67	      createShapeFromSvg: vi.fn(() => null),
 68	      createShapeFromSvgWithImages: vi.fn(),
 69	      uploadMediaData: vi.fn().mockResolvedValue({}),
 70	      uploadMediaUrl: vi.fn().mockResolvedValue({})
 71	    });
 72	  });
