562	/** Return a web URL only when the complete source value is a URL. */
563	export function sourceUrl(value: string): string | undefined {
564	  const trimmed = value.trim();
565	  if (!trimmed) return undefined;
566	  if (/\s/.test(trimmed)) return undefined;
567	  try {
568	    const parsed = new URL(trimmed);
569	    return parsed.protocol === "http:" || parsed.protocol === "https:" ? parsed.href : undefined;
570	  } catch {
571	    return undefined;
572	  }
573	}
