575	/**
576	 * Resolve the editor value into HTML. Pasted markup is returned unchanged;
577	 * a complete HTTP(S) URL is fetched by the browser first, with the hardened
578	 * fetch service taking over only when CORS or the network prevents it. The
579	 * final upstream URL (after redirects) becomes the asset base URL.
580	 */
581	export async function resolveSource(value: string, explicitBaseUrl?: string): Promise<ResolvedSource> {
582	  const url = sourceUrl(value);
583	  if (!url) {
584	    const styles = await inlineStylesheets(value, explicitBaseUrl);
585	    const images = await inlineImageAssets(styles, explicitBaseUrl);
586	    const fonts = await inlineWebFonts(images, explicitBaseUrl);
587	    const html = await inlineSvgImages(fonts, explicitBaseUrl);
588	    return { html, baseUrl: explicitBaseUrl || undefined };
589	  }
590	
591	  const response = await fetchDocument(url, "html");
592	  const html = await response.text();
593	  if (!html.trim()) throw new Error(`Unable to load ${url}: the response did not contain HTML.`);
594	  const baseUrl = explicitBaseUrl || response.headers.get("X-HTML-Source-URL") || url;
595	  const styles = await inlineStylesheets(html, baseUrl);
596	  const images = await inlineImageAssets(styles, baseUrl);
597	  const fonts = await inlineWebFonts(images, baseUrl);
598	
599	  return {
600	    html: await inlineSvgImages(fonts, baseUrl),
601	    baseUrl,
602	    sourceUrl: url
603	  };
604	}

