10	const dist = resolve(fileURLToPath(new URL("../dist/", import.meta.url)));
11	const host = process.env.HOST || "127.0.0.1";
12	const port = Number(process.env.PORT || 4173);
13	const types = { ".css": "text/css; charset=utf-8", ".html": "text/html; charset=utf-8", ".js": "text/javascript; charset=utf-8", ".json": "application/json; charset=utf-8", ".svg": "image/svg+xml" };
14	const fetchProxyPath = "/__html_to_penpot/fetch";
15	const maxHtmlBytes = 10 * 1024 * 1024;
16	const fetchTimeoutMs = 15_000;
17	
18	async function proxyHtml(target, response) {
19	  let targetUrl;
20	  try {
21	    targetUrl = new URL(target);
22	    if (targetUrl.protocol !== "http:" && targetUrl.protocol !== "https:") throw new Error("unsupported protocol");
23	  } catch {
24	    response.writeHead(400).end("The url must be an http(s) URL.");
25	    return;
26	  }
27	
28	  try {
29	    const upstream = await fetch(targetUrl, {
30	      headers: { Accept: "text/html,application/xhtml+xml;q=0.9,*/*;q=0.1" },
31	      redirect: "follow",
32	      signal: AbortSignal.timeout(fetchTimeoutMs)
33	    });
34	    if (!upstream.ok) {
35	      response.writeHead(upstream.status >= 400 && upstream.status < 500 ? upstream.status : 502).end(`The target server returned HTTP ${upstream.status}.`);
36	      return;
37	    }
38	
39	    const html = await upstream.text();
40	    if (Buffer.byteLength(html, "utf8") > maxHtmlBytes) {
41	      response.writeHead(413).end("The target page is larger than the 10 MB limit.");
42	      return;
43	    }
44	
45	    response.setHeader("Access-Control-Expose-Headers", "X-HTML-Source-URL");
46	    response.setHeader("Content-Type", "text/html; charset=utf-8");
47	    response.setHeader("Cache-Control", "no-store");
48	    response.setHeader("X-HTML-Source-URL", upstream.url || targetUrl.href);
49	    response.writeHead(200).end(html);
50	  } catch (error) {
51	    const detail = error instanceof Error ? error.message : "the proxy request failed";
52	    response.writeHead(502).end(`Unable to fetch the target page: ${detail}`);
53	  }
54	}
55	
56	createServer(async (request, response) => {
57	  response.setHeader("Access-Control-Allow-Origin", "*");
58	  response.setHeader("Cross-Origin-Resource-Policy", "cross-origin");
59	  if (request.method === "OPTIONS") return response.writeHead(204).end();
60	  const requestUrl = new URL(request.url || "/", `http://${request.headers.host}`);
61	  if (requestUrl.pathname === fetchProxyPath) {
62	    if (request.method !== "GET") return response.writeHead(405).end("Only GET is supported.");
63	    const target = requestUrl.searchParams.get("url");
64	    if (!target) return response.writeHead(400).end("Missing url query parameter.");
65	    return proxyHtml(target, response);
66	  }
67	  const pathname = decodeURIComponent(requestUrl.pathname);
68	  const relative = pathname === "/" ? "index.html" : pathname.replace(/^\/+/, "");
69	  const target = normalize(join(dist, relative));
70	  if (!target.startsWith(dist)) return response.writeHead(403).end("Forbidden");
71	  try {
72	    const info = await stat(target);
73	    if (!info.isFile()) throw new Error("Not a file");
74	    response.writeHead(200, { "Content-Type": types[extname(target)] || "application/octet-stream", "Cache-Control": "no-cache" });
75	    response.end(await readFile(target));
76	  } catch {
77	    response.writeHead(404).end("Not found");
78	  }
79	}).listen(port, host, () => console.log(`Ultimate HTML to Penpot: http://${host}:${port}/manifest.json`));
