378	/** Inline ordinary image assets so Penpot receives bytes instead of fetching remote URLs server-side. */
379	async function inlineImageAssets(html: string, baseUrl: string | undefined): Promise<string> {
380	  if (typeof DOMParser === "undefined") return html;
381	  const document = new DOMParser().parseFromString(html, "text/html");
382	  let changed = promoteLazyImages(document);
383	  const targets = new Set<string>();
384	  const images = [...document.querySelectorAll("img[src]")];
385	  for (const image of images) {
386	    const source = image.getAttribute("src");
387	    const target = source && absoluteAssetUrl(source, baseUrl);
388	    // SVG <img> elements are handled by the vector pass below. Keeping them
389	    // out of the raster budget ensures ordinary header/hero images win even
390	    // on pages with many social icons.
391	    if (target && !isSvgUrl(target)) targets.add(target);
392	  }
393	  for (const element of document.querySelectorAll("img[srcset], source[srcset]")) {
394	    for (const source of srcsetUrls(element.getAttribute("srcset") || "")) {
395	      const target = absoluteAssetUrl(source, baseUrl);
396	      if (target && !isSvgUrl(target)) targets.add(target);
397	    }
398	  }
399	  const svgImages = [...document.querySelectorAll<SVGImageElement>("svg image")];
400	  for (const image of svgImages) {
401	    const source = image.getAttribute("href") || image.getAttribute("xlink:href");
402	    const target = source && absoluteAssetUrl(source, baseUrl);
403	    if (target) targets.add(target);
404	  }
405	  for (const element of document.querySelectorAll("[style]")) {
406	    const style = element.getAttribute("style") || "";
407	    for (const match of style.matchAll(INLINE_STYLE_URL_PATTERN)) {
408	      const target = absoluteAssetUrl(match[2], baseUrl);
409	      if (target && likelyImageUrl(target)) targets.add(target);
410	    }
411	  }
412	  for (const style of document.querySelectorAll("style")) {
413	    // Font sources are presentation data and are handled by inlineWebFonts;
414	    // treating legacy SVG fonts as page images would consume the image budget.
415	    const css = (style.textContent || "").replace(FONT_FACE_PATTERN, "");
416	    for (const match of css.matchAll(INLINE_STYLE_URL_PATTERN)) {
417	      const target = absoluteAssetUrl(match[2], baseUrl);
418	      if (target && likelyImageUrl(target)) targets.add(target);
419	    }
420	  }
421	
422	  const dataUrls = new Map<string, string>();
423	  let totalBytes = 0;
424	  for (const target of [...targets].slice(0, MAX_INLINE_IMAGE_ASSETS)) {
425	    if (totalBytes >= MAX_INLINE_IMAGE_TOTAL_BYTES) break;
426	    try {
427	      const result = await imageDataUrl(target);
428	      if (!result || totalBytes + result.bytes > MAX_INLINE_IMAGE_TOTAL_BYTES) continue;
429	      dataUrls.set(target, result.dataUrl);
430	      totalBytes += result.bytes;
431	    } catch {
432	      // A blocked or unsupported image remains a best-effort remote asset.
433	    }
434	  }
435	  if (!dataUrls.size) return changed ? "<!doctype html>\n" + document.documentElement.outerHTML : html;
436	
437	  for (const image of images) {
438	    const source = image.getAttribute("src");
439	    const target = source && absoluteAssetUrl(source, baseUrl);
440	    const dataUrl = target && dataUrls.get(target);
441	    if (dataUrl) image.setAttribute("src", dataUrl);
442	  }
443	  for (const element of document.querySelectorAll("img[srcset], source[srcset]")) {
444	    const source = element.getAttribute("srcset") || "";
445	    const rewritten = rewriteSrcset(source, baseUrl, dataUrls);
446	    if (rewritten !== source) element.setAttribute("srcset", rewritten);
447	  }
448	  for (const image of svgImages) {
449	    const source = image.getAttribute("href") || image.getAttribute("xlink:href");
450	    const target = source && absoluteAssetUrl(source, baseUrl);
451	    const dataUrl = target && dataUrls.get(target);
452	    if (dataUrl) {
453	      if (image.hasAttribute("href")) image.setAttribute("href", dataUrl);
454	      if (image.hasAttribute("xlink:href")) image.setAttribute("xlink:href", dataUrl);
455	    }
456	  }
457	  for (const element of document.querySelectorAll("[style]")) {
458	    const style = element.getAttribute("style") || "";
459	    const rewritten = style.replace(INLINE_STYLE_URL_PATTERN, (match, _quote: string, source: string) => {
460	      const target = absoluteAssetUrl(source, baseUrl);
461	      const dataUrl = target && dataUrls.get(target);
462	      return dataUrl ? `url("${dataUrl}")` : match;
463	    });
464	    if (rewritten !== style) element.setAttribute("style", rewritten);
465	  }
466	  for (const element of document.querySelectorAll("style")) {
467	    const style = element.textContent || "";
468	    const rewritten = style.replace(INLINE_STYLE_URL_PATTERN, (match, _quote: string, source: string) => {
469	      const target = absoluteAssetUrl(source, baseUrl);
470	      const dataUrl = target && dataUrls.get(target);
471	      return dataUrl ? `url("${dataUrl}")` : match;
472	    });
473	    if (rewritten !== style) element.textContent = rewritten;
474	  }
475	  return "<!doctype html>\n" + document.documentElement.outerHTML;
476	}
