478	/** Turn a normalised service rejection into an actionable plugin error. */
479	async function describeProxyRejection(url: string, response: Response): Promise<string> {
480	  let reason = "";
481	  try {
482	    const payload = await response.json();
483	    if (payload && typeof payload.error === "string") reason = payload.error;
484	  } catch {
485	    // Non-JSON bodies carry no usable reason.
486	  }
487	  if (!reason) reason = `the import service rejected the request (HTTP ${response.status}).`;
488	  return `Unable to load ${url}: ${reason.endsWith(".") ? reason : `${reason}.`}`;
489	}
