491	/**
492	 * Fetch a document directly first; when the browser reports a CORS or network
493	 * failure, retry through the constrained fetch service. An answer from the
494	 * origin itself (any HTTP status) is authoritative and never retried.
495	 */
496	export async function fetchDocument(url: string, mode: AssetMode): Promise<Response> {
497	  try {
498	    const direct = await fetch(url, { credentials: "omit", redirect: "follow" });
499	    if (direct.ok) return direct;
500	    throw new UpstreamStatusError(`Unable to load ${url}: the server returned HTTP ${direct.status}.`);
501	  } catch (error) {
502	    if (error instanceof UpstreamStatusError) throw error;
503	    return await fetchThroughProxy(url, mode, error);
504	  }
505	}
506	
507	async function fetchThroughProxy(url: string, mode: AssetMode, directError: unknown): Promise<Response> {
508	  const proxyTarget = proxyUrlFor(url, mode);
509	  if (!proxyTarget) {
510	    throw new Error(
511	      `Unable to load ${url}. Paste the page HTML instead; direct URL loading requires browser CORS (${detailOf(directError)}) and no fetch service is configured.`
512	    );
513	  }
514	  let response: Response;
515	  try {
516	    response = await fetch(proxyTarget, { credentials: "omit" });
517	  } catch (proxyError) {
518	    throw new Error(
519	      `Unable to load ${url}. Direct loading was blocked by CORS (${detailOf(directError)}); the import service also failed (${detailOf(proxyError)}). Paste the page HTML instead.`
520	    );
521	  }
522	  if (!response.ok) throw new Error(await describeProxyRejection(url, response));
523	  return response;
524	}
