   534	async function inlineSvgImages(html: string, baseUrl: string | undefined): Promise<string> {
   535	  if (typeof DOMParser === "undefined") return html;
   536	  const document = new DOMParser().parseFromString(html, "text/html");
   537	  let changed = promoteLazyImages(document);
   538	  const images = [...document.querySelectorAll("img[src]")];
   539	  await Promise.all(images.map(async (image) => {
   540	    const source = image.getAttribute("src");

   540	    const source = image.getAttribute("src");
