   542	    const targetHref = absoluteAssetUrl(source, baseUrl);
   543	    if (!targetHref || !isSvgUrl(targetHref)) return;
   544	    const target = new URL(targetHref);
   545	    let response: Response;
   546	    try {
   547	      response = await fetchDocument(target.href, "svg");
   548	    } catch {
   549	      return; // Assets are best-effort; the page still imports.
   550	    }
   551	    const contentLength = Number(response.headers.get("content-length") || "0");
   552	    if (contentLength > MAX_INLINE_SVG_BYTES) return;
   553	    const svg = await response.text();
   554	    if (utf8ByteLength(svg) > MAX_INLINE_SVG_BYTES || !/<svg[\s>]/i.test(svg)) return;
