   556	    image.setAttribute("src", `data:image/svg+xml,${encodeURIComponent(normalized)}`);
   557	    changed = true;
   558	  }));
   559	  return changed ? "<!doctype html>\n" + document.documentElement.outerHTML : html;
   560	}
